import asyncio
import flet as ft
import themes as t
from services.battle_animation import get_sheet
from services.sprite_selector import sheet_selector
from components.unit_sprite import sheet_frame

# The character walking to the right (clip generated by tools/ro_to_sheet.py)
WALK_CLIP = "walk_se"
SPRITE_HEIGHT = 150


def travel_dialog(job: str):
    """Pop up shown while the character travels to another map: only his walking animation, in place.
    Returns (dialog, animate): `animate()` is a coroutine that plays the walk clip until it is cancelled.
    It is not an @ft.component because the dialog is created outside of a render (in an async task)."""
    sheet_name = sheet_selector(job)
    holder = ft.Container(width=200, height=170, alignment=ft.Alignment.CENTER)
    dialog = ft.AlertDialog(
        modal=True,   # no way to click around while traveling
        bgcolor=t.PANEL_BG,
        content=holder,
    )

    async def animate():
        if not sheet_name:
            return
        sheet = get_sheet(sheet_name)
        clip = sheet.clips[WALK_CLIP]
        box = clip.box or (0, 0, sheet.frame_w, sheet.frame_h)
        scale = SPRITE_HEIGHT / box[3]
        frame = 0
        while True:
            holder.content = sheet_frame(sheet, clip.row, frame % clip.frames, box, scale=scale)
            holder.update()
            frame += 1
            await asyncio.sleep(1 / clip.fps)

    return dialog, animate
